"""
build_scores_qwen.py -- single-annotator claim-level rubric scores for the
qwen2.5:7b responses (added as a 4th, non-Anthropic model to address the
"only Anthropic models" limitation). Same rubric, same annotator, same
calibration as scripts/build_scores.py. Appends to scoring/all_scores.json
rather than overwriting it.

Dimension keys: support, provenance, obs_inf, attribution, reproducibility
"""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SCORES_FILE = ROOT / "scoring" / "all_scores.json"

S = []


def add(case_id, model, claim, support, provenance, obs_inf, attribution, repro, note=""):
    S.append({
        "case_id": case_id, "model_requested": model, "claim": claim,
        "support": support, "provenance": provenance, "obs_inf": obs_inf,
        "attribution": attribution, "reproducibility": repro, "note": note,
    })


